const data = $input.first().json;
const items = [];

// Convert the response into separate items for each stock
for (const symbol in data) {
  if (data[symbol] && typeof data[symbol] === 'object') {
    items.push({
      json: {
        symbol: symbol,
        name: data[symbol].name || symbol,
        percent_change: parseFloat(data[symbol].percent_change),
        close: parseFloat(data[symbol].close),
        previous_close: parseFloat(data[symbol].previous_close),
        open: parseFloat(data[symbol].open),
        high: parseFloat(data[symbol].high),
        low: parseFloat(data[symbol].low),
        volume: data[symbol].volume,
        raw_data: data[symbol]
      }
    });
  }
}

return items;

const analysis = $input.first().json.content.parts[0].text ;

// Ensure proper formatting for email (preserve line breaks)
const formattedAnalysis = analysis
  .replace(/\n/g, '<br>')  // Convert to HTML breaks for HTML emails
  // OR keep as plain text with proper spacing:
  // .replace(/━/g, '─')  // Replace special chars if needed

return {
  json: {
    symbol: $('Get stock update').item.json.symbol,
    company: $('Get stock update').item.json.name,
    change: $('Convert values').item.json.percent_change,
    analysis_html: analysis.replace(/\n/g, '<br>'),
    analysis_plain: analysis,
    timestamp: new Date().toISOString()
  }
};
